<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Illuminate\Console\Command; use Pterodactyl\Services\Dezerx\Runtime; use Pterodactyl\Services\Dezerx\Catalogue\Index; class Prime extends Command { protected $signature = 'dezerx:prime'; protected $description = 'Warm the DezerX theme runtime.'; public function handle(): int { $key = trim((string) getenv('DZX_K')); $domain = strtolower(trim((string) getenv('DZX_D'))); if ($domain === '') { $domain = Index::host(); } if ($key !== '' && $domain !== '') { Index::hold($key, $domain); $r = Runtime::activate($key, $domain); $this->line(($r['ok'] ?? false) === true ? 'DZX:ACTIVE' : 'DZX:PENDING'); } else { $this->line('DZX:PENDING'); } return self::SUCCESS; } } 